using System.Collections.ObjectModel;
using System.Globalization;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using Microsoft.EntityFrameworkCore;
using POS_WPF.Data;
using POS_WPF.Domain.POS;
using POS_WPF.Domain.Promotions;
using POS_WPF.Domain.Sales;
using POS_WPF.Infrastructure.Printing;
using POS_WPF.Infrastructure.Security;
namespace POS_WPF;
public partial class PosWindow : UserControl
{
 private readonly BarcodeLookupService _barcode;private readonly SalePostingService _posting;private readonly IDbContextFactory<AppDbContext> _dbFactory;private readonly SessionContext _session;private readonly IReceiptPrinter _receiptPrinter;private readonly ObservableCollection<CartItem> _cart=[];private string? _lastReceipt;private decimal _invoiceDiscount;
 public PosWindow(BarcodeLookupService barcode,SalePostingService posting,IDbContextFactory<AppDbContext> dbFactory,SessionContext session,IReceiptPrinter receiptPrinter){InitializeComponent();_barcode=barcode;_posting=posting;_dbFactory=dbFactory;_session=session;_receiptPrinter=receiptPrinter;CartGrid.ItemsSource=_cart;Loaded+=async(_,_)=>{await LoadPopularProductsAsync();await LoadHeldAsync();BarcodeBox.Focus();RefreshTotal();};}
 private async Task LoadPopularProductsAsync(){await using var db=await _dbFactory.CreateDbContextAsync();var sold=await db.Set<SaleLine>().Where(l=>db.Sales.Any(s=>s.Id==EF.Property<Guid>(l,"SaleId")&&s.Status==SaleStatus.Completed)).GroupBy(l=>l.ProductId).Select(g=>new{ProductId=g.Key,Sold=g.Sum(x=>x.Quantity*x.ConversionFactor)}).OrderByDescending(x=>x.Sold).Take(12).ToListAsync();if(sold.Count==0){PopularProductsPanel.ItemsSource=Array.Empty<PopularProduct>();return;}var ids=sold.Select(x=>x.ProductId).ToList();var products=await db.Products.AsNoTracking().Where(x=>ids.Contains(x.Id)&&x.IsActive).Include(x=>x.Units).ToListAsync();PopularProductsPanel.ItemsSource=sold.Join(products,x=>x.ProductId,x=>x.Id,(x,p)=>{var unit=p.Units.SingleOrDefault(u=>u.Id==p.BaseUnitId)??p.Units.SingleOrDefault(u=>u.IsBaseUnit);return new PopularProduct(p.Id,unit?.Id??Guid.Empty,p.Name,unit?.SellingPrice??0m,x.Sold,unit?.Name??"PCS");}).ToList();}
 private async void PopularProduct_Click(object sender,RoutedEventArgs e){if(sender is not FrameworkElement{DataContext:PopularProduct item})return;try{if(item.UnitId==Guid.Empty)throw new InvalidOperationException("The product has no base selling unit.");var existing=_cart.FirstOrDefault(x=>x.ProductId==item.ProductId&&x.UnitId==item.UnitId);if(existing is null){existing=new CartItem(item.ProductId,item.UnitId,item.Name,item.UnitName,1m,item.Price);_cart.Add(existing);}else existing.Quantity+=1;await ApplyPromotionAsync(existing);RefreshTotal();Status($"Added {item.Name}.",true);}catch(Exception ex){Status(ex.Message,false);}}
 private async void Barcode_KeyDown(object sender,KeyEventArgs e){if(e.Key==Key.Enter){e.Handled=true;await AddBarcodeAsync();}}private async void Add_Click(object sender,RoutedEventArgs e)=>await AddBarcodeAsync();
 private async Task AddBarcodeAsync(){var code=BarcodeBox.Text.Trim();if(code.Length==0)return;try{var match=await _barcode.FindAsync(code);if(match is null){Status("Barcode not found.",false);return;}if(!match.Unit.CanSell){Status("This unit is not sellable.",false);return;}var existing=_cart.FirstOrDefault(x=>x.ProductId==match.Product.Id&&x.UnitId==match.Unit.Id);if(existing is null){existing=new CartItem(match.Product.Id,match.Unit.Id,match.Product.Name,match.Unit.Name,match.Unit.ConversionFactorToBase,match.Unit.SellingPrice);_cart.Add(existing);}else existing.Quantity+=1;await ApplyPromotionAsync(existing);RefreshTotal();Status($"Added {match.Product.Name} ({match.Unit.Abbreviation}).",true);}catch(Exception ex){Status(ex.InnerException?.Message??ex.Message,false);}finally{BarcodeBox.Clear();BarcodeBox.Focus();}}
 private async Task ApplyPromotionAsync(CartItem item){item.PromotionDiscount=0;item.PromotionId=null;item.AppliedPromotionQuantity=0;await using var db=await _dbFactory.CreateDbContextAsync();var now=DateTime.UtcNow;var promotions=await db.Promotions.AsNoTracking().Where(x=>x.IsActive&&x.ProductId==item.ProductId&&(!x.UnitId.HasValue||x.UnitId==item.UnitId)).OrderByDescending(x=>x.StartsAtUtc).ToListAsync();var promotion=promotions.FirstOrDefault(x=>x.IsCurrentlyActive(now));if(promotion is null)return;var eligibleQuantity=item.Quantity;if(promotion.MaxQuantity.HasValue)eligibleQuantity=Math.Min(eligibleQuantity,Math.Max(0,promotion.MaxQuantity.Value-promotion.ConsumedQuantity));if(eligibleQuantity<=0)return;var lineBase=item.Quantity*item.UnitPrice;switch(promotion.Type){case PromotionType.Percentage:item.PromotionDiscount=Math.Round(lineBase*(promotion.Value/100m)*(eligibleQuantity/item.Quantity),2,MidpointRounding.AwayFromZero);item.AppliedPromotionQuantity=eligibleQuantity;break;case PromotionType.FixedAmount:item.PromotionDiscount=Math.Min(lineBase*(eligibleQuantity/item.Quantity),promotion.Value);item.AppliedPromotionQuantity=eligibleQuantity;break;case PromotionType.QuantityDiscount:{var groups=Math.Floor(eligibleQuantity/promotion.MinimumQuantity);var promoQty=groups*promotion.MinimumQuantity;item.PromotionDiscount=Math.Max(0,groups*(promotion.MinimumQuantity*item.UnitPrice-promotion.Value));item.AppliedPromotionQuantity=promoQty;break;}case PromotionType.BuyXGetY:{var groups=Math.Floor(eligibleQuantity/promotion.MinimumQuantity);var freeQty=groups*promotion.RewardQuantity;item.PromotionDiscount=Math.Min(lineBase,freeQty*item.UnitPrice);item.AppliedPromotionQuantity=groups*promotion.MinimumQuantity;break;}}item.PromotionName=promotion.Name;item.PromotionId=promotion.Id;}
 private async void Cart_CellEditEnding(object sender,DataGridCellEditEndingEventArgs e){if(e.Row.Item is not CartItem item)return;Dispatcher.BeginInvoke(async()=>{if(item.Quantity<=0){_cart.Remove(item);RefreshTotal();return;}if(item.ManualDiscount<0)item.ManualDiscount=0;await ApplyPromotionAsync(item);RefreshTotal();});}
 private void ApplyInvoiceDiscount_Click(object sender,RoutedEventArgs e){if(!decimal.TryParse(InvoiceDiscountBox.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var discount)||discount<0){Status("Enter a valid invoice discount.",false);return;}var max=Math.Max(0,_cart.Sum(x=>x.Quantity*x.UnitPrice-x.ManualDiscount-x.PromotionDiscount+x.Tax));if(discount>max)discount=max;_invoiceDiscount=discount;InvoiceDiscountBox.Text=discount.ToString("N2",CultureInfo.CurrentCulture);RefreshTotal();Status("Invoice discount applied.",true);}
 private void VoidLine_Click(object sender,RoutedEventArgs e){if(CartGrid.SelectedItem is not CartItem item){Status("Select a cart line first.",false);return;}_cart.Remove(item);RefreshTotal();Status("Cart line removed.",true);}
 private void ClearCart_Click(object sender,RoutedEventArgs e){_cart.Clear();_invoiceDiscount=0;InvoiceDiscountBox.Text="0.00";OrderNumberText.Text="New Sale";RefreshTotal();Status("Cart cleared.",true);}
 private async Task LoadHeldAsync(){if(_session.CurrentUser is null){HeldOrdersBox.ItemsSource=null;return;}await using var db=await _dbFactory.CreateDbContextAsync();HeldOrdersBox.ItemsSource=await db.HeldSales.AsNoTracking().Where(x=>x.CashierId==_session.CurrentUser.Id&&!x.IsReleased).OrderByDescending(x=>x.CreatedAtUtc).Select(x=>new HeldOrderOption(x.Id,$"{x.Reference} · {x.CreatedAtUtc.ToLocalTime():HH:mm}")).ToListAsync();}
 private async void Hold_Click(object sender,RoutedEventArgs e){if(_cart.Count==0){Status("An empty cart cannot be held.",false);return;}if(_session.CurrentUser is null){Status("Session expired.",false);return;}try{var reference=string.IsNullOrWhiteSpace(HoldLabelBox.Text)?$"HOLD-{DateTime.Now:HHmmss}":HoldLabelBox.Text.Trim();var payload=JsonSerializer.Serialize(new HeldCartPayload(_cart.Select(x=>new CartSnapshot(x.ProductId,x.UnitId,x.ProductName,x.UnitName,x.ConversionFactor,x.UnitPrice,x.Quantity,x.ManualDiscount,x.PromotionDiscount,x.Tax,x.PromotionId,x.AppliedPromotionQuantity,x.PromotionName)).ToList(),_invoiceDiscount));await using var db=await _dbFactory.CreateDbContextAsync();db.HeldSales.Add(new HeldSale(reference,_session.CurrentUser.Id,payload));await db.SaveChangesAsync();_cart.Clear();_invoiceDiscount=0;InvoiceDiscountBox.Text="0.00";HoldLabelBox.Clear();OrderNumberText.Text="New Sale";RefreshTotal();await LoadHeldAsync();Status($"Order held successfully: {reference}.",true);}catch(Exception ex){Status(ex.InnerException?.Message??ex.Message,false);}}
 private async void Recall_Click(object sender,RoutedEventArgs e){if(HeldOrdersBox.SelectedValue is not Guid id){Status("Select a held order first.",false);return;}if(_cart.Count>0){Status("Clear or hold the current cart before recalling another order.",false);return;}try{await using var db=await _dbFactory.CreateDbContextAsync();var held=await db.HeldSales.SingleAsync(x=>x.Id==id&&!x.IsReleased);var payload=JsonSerializer.Deserialize<HeldCartPayload>(held.Payload)??throw new InvalidOperationException("Held order data is invalid.");foreach(var x in payload.Items){var item=new CartItem(x.ProductId,x.UnitId,x.ProductName,x.UnitName,x.ConversionFactor,x.UnitPrice){Quantity=x.Quantity,ManualDiscount=x.ManualDiscount,PromotionDiscount=x.PromotionDiscount,Tax=x.Tax,PromotionId=x.PromotionId,AppliedPromotionQuantity=x.AppliedPromotionQuantity,PromotionName=x.PromotionName};_cart.Add(item);}_invoiceDiscount=payload.InvoiceDiscount;InvoiceDiscountBox.Text=_invoiceDiscount.ToString("N2",CultureInfo.CurrentCulture);held.IsReleased=true;await db.SaveChangesAsync();OrderNumberText.Text=held.Reference;await LoadHeldAsync();RefreshTotal();Status($"Held order recalled: {held.Reference}.",true);}catch(Exception ex){Status(ex.InnerException?.Message??ex.Message,false);}}
 private async void Complete_Click(object sender,RoutedEventArgs e){var total=_cart.Sum(x=>x.LineTotal)-_invoiceDiscount;if(_cart.Count==0){Status("Cart is empty.",false);return;}if(total<0)total=0;if(!decimal.TryParse(PaymentBox.Text,NumberStyles.Number,CultureInfo.CurrentCulture,out var payment)||payment<total){Status($"Payment must be at least {total:N2}.",false);PaymentBox.Focus();PaymentBox.SelectAll();return;}try{await using var db=await _dbFactory.CreateDbContextAsync();var branch=await db.Branches.Where(x=>x.IsActive).OrderBy(x=>x.Code).FirstOrDefaultAsync();if(branch is null){Status("No active branch is configured.",false);return;}var warehouse=await db.Warehouses.Where(x=>x.IsActive&&x.BranchId==branch.Id).OrderBy(x=>x.Code).FirstOrDefaultAsync();var terminal=await db.Terminals.Where(x=>x.IsActive&&x.BranchId==branch.Id).OrderBy(x=>x.Code).FirstOrDefaultAsync();var register=await db.CashRegisters.Where(x=>x.IsOpen&&x.BranchId==branch.Id).OrderBy(x=>x.Code).FirstOrDefaultAsync();if(warehouse is null){Status("No active warehouse is configured for the branch.",false);return;}if(terminal is null){Status("No active POS terminal is configured for the branch.",false);return;}if(register is null){Status("Open a cash register before selling.",false);return;}if(_session.CurrentUser is null){Status("Session expired. Please sign in again.",false);return;}var number=$"S-{DateTime.UtcNow:yyyyMMddHHmmssfff}";var requests=_cart.Select(x=>new SaleLineRequest(x.ProductId,x.UnitId,x.Quantity,x.UnitPrice,x.Discount,x.Tax)).ToList();if(_invoiceDiscount>0&&requests.Count>0){var first=requests[0];requests[0]=first with{Discount=first.Discount+_invoiceDiscount};}var method=(PaymentMethodBox.SelectedItem as ComboBoxItem)?.Content?.ToString()??"Cash";var request=new SalePostingRequest(branch.Id,warehouse.Id,terminal.Id,register.Id,_session.CurrentUser.Id,number,null,requests,[new SalePaymentRequest(method,payment)]);var result=await _posting.PostAsync(request);foreach(var item in _cart.Where(x=>x.PromotionId.HasValue&&x.AppliedPromotionQuantity>0)){var promo=await db.Promotions.SingleOrDefaultAsync(x=>x.Id==item.PromotionId.Value);if(promo is not null){promo.ConsumedQuantity+=item.AppliedPromotionQuantity;if(promo.MaxQuantity.HasValue&&promo.ConsumedQuantity>=promo.MaxQuantity.Value)promo.IsActive=false;}}await db.SaveChangesAsync();_lastReceipt=BuildReceipt(number,result.Total,result.Change);_cart.Clear();_invoiceDiscount=0;InvoiceDiscountBox.Text="0.00";PaymentBox.Text="0.00";OrderNumberText.Text="New Sale";RefreshTotal();await LoadPopularProductsAsync();await LoadHeldAsync();Status($"Sale completed successfully. Change: {result.Change:N2}",true);try{await _receiptPrinter.PrintAsync(new PrintDocumentRequest(string.Empty,_lastReceipt,"80mm"));Status($"Sale completed successfully. Change: {result.Change:N2} · Receipt printed.",true);}catch(Exception printEx){Status($"Sale is saved, but receipt printing failed: {printEx.Message}",false);}}catch(Exception ex){Status(ex.InnerException?.Message??ex.Message,false);}finally{BarcodeBox.Focus();}}
 private async void PrintLast_Click(object sender,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(_lastReceipt)){Status("No receipt available for reprint.",false);return;}try{await _receiptPrinter.PrintAsync(new PrintDocumentRequest(string.Empty,_lastReceipt,"80mm"));Status("Receipt printed successfully.",true);}catch(Exception ex){Status(ex.Message,false);}}
 private string BuildReceipt(string number,decimal total,decimal change)=>$"RETAIL POS\n{number}\n------------------------------\nTOTAL: {total:N2}\nCHANGE: {change:N2}\nThank you\n";
 private void RefreshTotal(){foreach(var item in _cart){var maxManual=Math.Max(0,item.Quantity*item.UnitPrice-item.PromotionDiscount);if(item.ManualDiscount>maxManual)item.ManualDiscount=maxManual;}var subtotal=_cart.Sum(x=>x.Quantity*x.UnitPrice);var lineDiscount=_cart.Sum(x=>x.Discount);var tax=_cart.Sum(x=>x.Tax);var maxInvoice=Math.Max(0,subtotal-lineDiscount+tax);if(_invoiceDiscount>maxInvoice)_invoiceDiscount=maxInvoice;var total=Math.Max(0,subtotal-lineDiscount-_invoiceDiscount+tax);SubtotalText.Text=subtotal.ToString("N2",CultureInfo.CurrentCulture);DiscountText.Text=(lineDiscount+_invoiceDiscount).ToString("N2",CultureInfo.CurrentCulture);TotalText.Text=total.ToString("N2",CultureInfo.CurrentCulture);PaymentBox.Text=total.ToString("N2",CultureInfo.CurrentCulture);CartGrid.Items.Refresh();}
 private void Status(string message,bool success){StatusText.Foreground=success?System.Windows.Media.Brushes.DarkGreen:System.Windows.Media.Brushes.DarkRed;StatusText.Text=success?"✓  "+message:"⚠  "+message;}
 private sealed record PopularProduct(Guid ProductId,Guid UnitId,string Name,decimal Price,decimal Sold,string UnitName){public string PriceText=>Price.ToString("N2",CultureInfo.CurrentCulture);public string SoldText=>$"Sold: {Sold:N0} {UnitName}";}private sealed record HeldOrderOption(Guid Id,string Display);private sealed record HeldCartPayload(List<CartSnapshot> Items,decimal InvoiceDiscount);private sealed record CartSnapshot(Guid ProductId,Guid UnitId,string ProductName,string UnitName,decimal ConversionFactor,decimal UnitPrice,decimal Quantity,decimal ManualDiscount,decimal PromotionDiscount,decimal Tax,Guid? PromotionId,decimal AppliedPromotionQuantity,string? PromotionName);private sealed class CartItem(Guid productId,Guid unitId,string productName,string unitName,decimal conversionFactor,decimal unitPrice){public Guid ProductId{get;}=productId;public Guid UnitId{get;}=unitId;public string ProductName{get;}=productName;public string UnitName{get;}=unitName;public decimal ConversionFactor{get;}=conversionFactor;public decimal UnitPrice{get;}=unitPrice;public decimal ManualDiscount{get;set;}public decimal PromotionDiscount{get;set;}public decimal Tax{get;set;}public decimal Quantity{get;set;}=1;public Guid? PromotionId{get;set;}public decimal AppliedPromotionQuantity{get;set;}public string? PromotionName{get;set;}public decimal Discount=>ManualDiscount+PromotionDiscount;public decimal LineTotal=>Math.Max(0,Quantity*UnitPrice-Discount+Tax);}
}